"""Original model questions for in-app review and three unit mocks; no licensed question text."""
from common import question, table, save
import json,collections
from pathlib import Path
MODEL='https://docs.oracle.com/en/database/oracle/sql-developer-data-modeler/24.3/dmdug/data-modeler-concepts-usage.html'
CONSTRAINT='https://docs.oracle.com/en/database/oracle/oracle-database/19/sqlrf/constraint.html'
NORMAL='https://cs.uwaterloo.ca/~tozsu/courses/cs448/notes/5.Normalization.pdf'
TRANS='https://docs.oracle.com/en/database/oracle/oracle-database/19/cncpt/transactions.html'
DB='https://docs.oracle.com/en/database/oracle/oracle-database/19/cncpt/introduction-to-oracle-database.html'
DENORM='https://cvw.cac.cornell.edu/RelationalDBs/design-create/denormalization'
BANK={};REVIEW={};CURRENT=''
def lesson(part,n):
 global CURRENT
 CURRENT=f'{part}-{n:02d}';BANK.setdefault(part,[]);REVIEW.setdefault(part,[])
def rows(text):
 part=CURRENT[:3]
 for line in text.strip().splitlines():
  if not line.strip():continue
  bits=line.split('|');assert len(bits)==7,(CURRENT,line)
  level,stem,good,w1,w2,w3,why=bits
  review=level.startswith('R');level=level[-1]
  target=REVIEW[part] if review else BANK[part]
  n=sum(q['lessonId']==CURRENT for q in target)+1
  qid=f'unit-{CURRENT}-'+('r' if review else 'm')+f'{n:02d}'
  source=MODEL if part=='1-1' else ({1:DB,2:CONSTRAINT,3:CONSTRAINT,4:TRANS,5:NORMAL,6:NORMAL,7:DENORM}[int(CURRENT[-2:])])
  kind='concept' if level=='B' else 'case'
  target.append(question(qid,CURRENT,kind,{'B':'basic','I':'intermediate','A':'advanced'}[level],stem,[good,w1,w2,w3],0,why,source=source))

lesson('1-1',1)
rows('''
RB|공유 학생 명부의 저장·검색·회복을 관리하는 Oracle 소프트웨어는 무엇인가?|DBMS|학생 데이터 한 행|업무 정보 자체|외부 스키마 하나|Oracle은 데이터를 관리하는 프로그램이다. 학생 한 행은 저장 대상이며, 정보는 해석 결과이고 외부 스키마는 사용자 관점의 구조다.
RI|박강열의 점수 82와 반 평균 70을 비교해 평균보다 높다고 판단했다. 정보에 해당하는 것은?|평균보다 높다는 해석|저장 주소|숫자 82만|파일 이름|정보는 값에 의미를 부여한 결과다. 82는 원자료이고 주소와 파일 이름은 이 비교의 해석 결과가 아니다.
RA|두 부서가 같은 고객 연락처를 독립 수정해 서로 다른 값을 보유한다. 통합 DB 도입의 핵심 개선 목표는?|공통 사실의 변경을 통제|중복 바이트 완전 제거|모든 조회 시간 0초|사용자 동시 접근 금지|동일 연락처의 기준과 갱신 규칙을 통합한다. DB도 필요 중복은 둘 수 있고 응답 시간 0이나 동시 접근 금지를 뜻하지 않는다.
B|업무에서 여러 사용자가 함께 사용하는 관련 데이터 집합을 가리키는 용어는?|데이터베이스|DBMS 실행 파일|컴파일러|네트워크 카드|DB는 관리 대상 데이터의 집합이다. 이를 관리하는 DBMS, 코드를 번역하는 컴파일러, 통신 장치와 구별한다.
B|데이터베이스의 계속적인 변화에 해당하는 동작은?|입학·휴학에 따라 학적이 갱신됨|개발 후 데이터 수정 금지|모든 값이 매초 변경됨|조회마다 표 구조 재생성|업무 상태에 맞춰 데이터가 변한다는 뜻이다. 모든 값의 주기적 변경이나 구조 재생성, 수정 금지는 요구하지 않는다.
B|내용 기반 참조를 가장 잘 보여 주는 요구는?|학과가 전자인 학생 검색|디스크 4번 블록 직접 읽기|파일의 20번째 바이트 읽기|메모리 주소 1000 접근|속성값인 학과로 대상을 찾는다. 나머지는 저장 위치를 직접 지정하므로 내용 기반 조건 검색과 다르다.
I|도서관과 행정실이 학생 이름을 함께 조회하되 연락처는 행정실에만 허용한다. 공유 DB의 적절한 해석은?|공유와 권한 제한은 함께 가능|공유하면 모든 열 공개 필수|권한이 다르면 반드시 별도 DB|연락처 열을 전체 삭제해야 함|같은 데이터베이스에서 사용자별 권한·관점을 달리할 수 있다. 공유는 무제한 공개나 중복 DB, 원본 삭제를 요구하지 않는다.
I|예약 좌석이 한 개 남았다. 두 요청이 동시에 성공했다고 응답해 중복 예약됐다. DBMS가 특히 통제해야 할 기능은?|동시성 제어|글자색 지정|엔터티 이름 번역|파일 확장자 변경|같은 자원에 대한 동시 변경이 업무 규칙을 깨지 않게 제어해야 한다. 화면·명명·확장자는 경쟁 상태를 해결하지 못한다.
I|저장 장애 후 확정된 주문을 복구하려 한다. DBMS의 어떤 관리 기능과 직접 관련되는가?|회복 관리|화면 배치|관계명 작명|개념적 추상화|회복은 장애 후 데이터 상태를 복구하는 기능이다. 배치와 작명은 표현 문제이며 추상화는 설계에서 대상 특징을 선택하는 일이다.
I|전산실이 조회 응답은 항상 0초라고 DB의 실시간 접근성을 설명했다. 올바른 평가는?|필요 시 접근 가능하다는 특성과 성능 보장을 혼동했다|실시간이면 물리적 지연이 없다|DB에는 검색 과정이 없다|동시 사용자가 한 명이어야 한다|실시간 접근은 업무 요구에 응답할 수 있음을 뜻한다. 검색·통신 지연이 사라지거나 사용자 수가 하나로 제한되지는 않는다.
I|학적 원본을 한 곳에서 관리하지만 검색용 인덱스에 학번이 다시 저장된다. 평가로 적절한 것은?|통제된 중복은 통합 DB와 양립한다|중복이 있어 DB가 아니다|인덱스는 반드시 삭제해야 한다|학번은 더 이상 식별자가 아니다|통합은 불필요한 중복과 불일치를 줄이는 목적이다. 접근용 중복이 있다는 이유로 DB나 식별자 성질이 사라지지 않는다.
I|교수는 성적을 입력하고 학생은 성적을 조회한다. 운영 데이터에 해당하는 것은?|실제 업무의 성적 기록|DBMS 설치 설명서만|개발자 개인 메모만|삭제된 테스트 이미지뿐|운영 데이터는 실제 업무 수행에 필요한 기록이다. 프로그램 문서나 개발 메모, 무관한 파일만으로 운영 성적을 대신하지 못한다.
I|주소가 바뀐 회원을 찾기 위해 회원번호로 조회한다. 저장 파일 위치를 몰라도 가능한 이유는?|논리적 조건으로 데이터를 참조|모든 파일을 사용자가 직접 지정|주소 값이 자동으로 기본키가 됨|DB에는 물리 저장이 없음|조건에 맞는 데이터를 찾는 방법과 물리 저장은 분리된다. 물리 저장 자체가 없거나 주소가 키가 되는 것은 아니다.
I|성적표 원본은 유지하면서 컴퓨터학과 학생만 보여 주었다. 이때 발생한 일은?|조건에 맞는 데이터 조회|전자학과 데이터 삭제|전체 DB 구조 변경|사용 권한 자동 회수|선택 조건은 결과 범위를 정한다. 조회만으로 조건 밖 원본을 지우거나 구조·권한을 바꾸지 않는다.
I|지점별 재고 파일을 통합했지만 모든 지점이 동시에 수정할 때 수량이 틀린다. 가장 정확한 판단은?|통합 저장만으로 일관성이 보장되지는 않는다|파일 수만 하나면 일관성 완성|DB는 동시에 수정할 수 없다|재고를 문자열로 바꾸면 해결|동시성·제약·트랜잭션 규칙도 필요하다. 파일 수와 자료형만으로 경쟁 갱신을 해결할 수 없다.
I|장정훈은 원점수 표와 과목 평균 보고서를 비교했다. 원점수와 보고서의 관계는?|데이터를 처리해 정보를 얻을 수 있다|정보는 반드시 숫자가 아니다|원점수는 저장할 수 없다|평균은 항상 사실과 무관하다|처리·해석한 평균도 숫자 형태의 정보가 될 수 있다. 데이터와 정보의 구별은 숫자 여부나 저장 가능성만으로 하지 않는다.
A|공동 명부가 두 서버에 복제되어 있다. 한 서버 장애에도 동일 기준으로 업무를 계속한다. 통합 DB라는 판단에 가장 중요한 것은?|공유 사실과 정합성 관리 기준|물리 파일이 정확히 하나인지|서버 이름이 같은지|모든 사용자의 화면이 같은지|논리적 통합과 관리가 핵심이며 물리적 복제 자체는 배제되지 않는다. 파일 수·서버명·화면 동일성은 통합의 필수 정의가 아니다.
A|같은 판매 원자료로 재무팀은 월매출, 물류팀은 출고량을 계산한다. 설명으로 적절한 것은?|같은 데이터도 목적에 따라 다른 정보가 된다|정보는 원자료마다 하나뿐이다|두 결과 중 하나는 반드시 오류다|공유하면 가공 목적도 같아야 한다|정보는 사용 목적과 해석 맥락에 따른다. 월매출과 출고량은 서로 다른 질문에 답하므로 동시에 타당할 수 있다.
A|중복 제거만을 목표로 주문 당시 주소를 지우고 현재 회원 주소만 남겼다. 과거 배송 재현이 불가능해졌다. 설계 평가로 적절한 것은?|과거 시점의 별도 사실을 잘못 제거했다|모든 중복 제거는 항상 개선이다|DBMS는 과거 사실을 저장할 수 없다|회원 이름만 있으면 주소를 복원한다|현재 주소와 주문 당시 주소는 시간 의미가 다른 사실이다. 문자열이 같았다는 이유만으로 지우면 이력을 잃으며 이름으로 복원되지 않는다.
''')
