def finalize(part,title):
    bank=BANK[part];review=REVIEW[part]
    assert len(bank)==150,(part,len(bank))
    expected_lessons=9 if part=='1-1' else 7
    assert len(review)==expected_lessons*3
    assert len({q['lessonId'] for q in bank})==expected_lessons
    assert collections.Counter(q['difficulty'] for q in bank)=={'basic':30,'intermediate':90,'advanced':30}
    assert len({q['stem'] for q in review+bank})==len(review)+len(bank)
    exams=[[] for _ in range(3)]
    for difficulty in ['basic','intermediate','advanced']:
        for i,q in enumerate(x for x in bank if x['difficulty']==difficulty):exams[i%3].append(q)
    import random
    for form,exam in enumerate(exams,1):
        random.Random(f'original-model-{part}-{form}').shuffle(exam)
        assert len(exam)==50 and len({q['lessonId'] for q in exam})==expected_lessons
        assert collections.Counter(q['difficulty'] for q in exam)=={'basic':10,'intermediate':30,'advanced':10}
        assert sum(q['type']=='case' for q in exam)>=25
        for q in exam:q['formId']=f'unit:{part}:{form}'
    for q in review+bank:
        assert q['id'].startswith('unit-')
        assert len(q['choices'])==len(set(q['choices']))==4
        assert 0<=q['answerIndex']<4
        q['reviewStatus']='author_reviewed_pending_independent_review'
        q['verification']='document_reasoning_not_engine_execution'
        q['familyId']=q['id']
    save(part,title,review,exams)

finalize('1-1','데이터 모델링의 이해')
